/* Auto-generated listening configs for ENGLISH_BOOK. Do not edit by hand. */
window.PRACTICE_EXTRA = Object.assign(window.PRACTICE_EXTRA || {}, {"au1":{"caption":{"zh":"听咖啡馆点单对话,先答题再点「显示原文」核对。","en":"A café ordering dialogue — answer first, then reveal the transcript."},"listening":{"intro":{"zh":"听一段咖啡馆里的点单对话,然后回答下面的问题。","en":"Listen to a conversation at a café, then answer the questions below."},"lines":[{"who":"A","en":"Hi there! What can I get for you today?","zh":"你好!今天想喝点什么?"},{"who":"B","en":"Could I get a medium latte, please?","zh":"我要一杯中杯拿铁,谢谢。"},{"who":"A","en":"Sure. Would you like that hot or iced?","zh":"好的。要热的还是冰的?"},{"who":"B","en":"Iced, please. And could you make it with oat milk?","zh":"冰的,谢谢。能换成燕麦奶吗?"},{"who":"A","en":"Of course. Anything to eat with that?","zh":"当然。要不要配点吃的?"},{"who":"B","en":"Is the blueberry muffin fresh today?","zh":"蓝莓马芬今天新鲜吗?"},{"who":"A","en":"It came out of the oven about an hour ago.","zh":"大约一小时前刚出炉。"},{"who":"B","en":"Perfect, I'll take one. For here, please.","zh":"太好了,来一个。堂食,谢谢。"},{"who":"A","en":"That comes to five ninety. Can I get a name for the order?","zh":"一共 5.90 美元。点单用什么名字?"},{"who":"B","en":"It's Maya — that's M-A-Y-A.","zh":"叫 Maya——M-A-Y-A。"}]},"quiz":[{"type":"mc","prompt":{"zh":"What exactly does the customer order to drink?","en":"What exactly does the customer order to drink?"},"options":["An iced latte with oat milk","A hot latte with normal milk","A cup of green tea","An iced mocha"],"correct":0,"feedback":{"zh":"她要 medium latte,iced,oat milk → 冰燕麦奶拿铁。","en":"Medium latte, iced, with oat milk."}},{"type":"mc","prompt":{"zh":"What does the customer decide to eat?","en":"What does the customer decide to eat?"},"options":["A croissant","A chocolate cookie","A blueberry muffin","Nothing at all"],"correct":2,"feedback":{"zh":"她问蓝莓马芬是否新鲜,然后说「I'll take one」。","en":"She takes the blueberry muffin."}},{"type":"mc","prompt":{"zh":"Why does the barista say the muffin is a good choice?","en":"Why does the barista say the muffin is a good choice?"},"options":["It is on special offer","It is the last one left","It has no sugar","It is fresh — baked about an hour ago"],"correct":3,"feedback":{"zh":"\"came out of the oven about an hour ago\" = 刚出炉、新鲜。","en":"It was baked about an hour ago."}},{"type":"mc","prompt":{"zh":"Will the customer eat in or take the order away?","en":"Will the customer eat in or take the order away?"},"options":["Eat in — she says \"for here\"","Take it away","Have it delivered","She hasn't decided"],"correct":0,"feedback":{"zh":"\"For here\" = 堂食(相对 to go 外带)。","en":"\"For here\" means eat in."}},{"type":"mc","prompt":{"zh":"How much does the order cost?","en":"How much does the order cost?"},"options":["$5.09","$9.50","$15.90","$5.90"],"correct":3,"feedback":{"zh":"\"five ninety\" = $5.90。","en":"\"Five ninety\" = $5.90."}}]},"au2":{"caption":{"zh":"听一段问路对话,先答题再看原文核对路线。","en":"A dialogue about asking for directions — answer first, then check the route in the transcript."},"listening":{"intro":{"zh":"听一位游客向当地人问路的对话,记下路线和地标,然后回答问题。","en":"Listen to a lost visitor asking a local for directions. Note the route and landmarks, then answer the questions below."},"lines":[{"who":"A","en":"Excuse me, sorry to bother you. I think I'm a bit lost — could you tell me the way to the train station?","zh":"打扰一下,抱歉打扰您。我好像有点迷路了——能告诉我去火车站怎么走吗?"},{"who":"B","en":"No problem at all. It's not far from here — about a ten-minute walk.","zh":"完全没问题。离这儿不远——大概走十分钟。"},{"who":"A","en":"Oh, that's good to hear. So which way should I go?","zh":"哦,那太好了。那我该往哪边走呢?"},{"who":"B","en":"Right. Go straight down King Street until you reach the traffic lights.","zh":"好的。沿着 King Street 一直走,直到红绿灯那里。"},{"who":"A","en":"Straight down King Street, all the way to the traffic lights. Got it.","zh":"沿 King Street 一直走到红绿灯。明白了。"},{"who":"B","en":"At the lights, turn left onto Queen Street. You'll walk past a big supermarket on your left.","zh":"到红绿灯左转,拐上 Queen Street。你会经过左手边一家大超市。"},{"who":"A","en":"Okay — left at the lights, then past the supermarket.","zh":"好——在红绿灯左转,然后经过那家超市。"},{"who":"B","en":"Exactly. Keep going until you come to a roundabout, and take the second exit.","zh":"没错。继续走,直到一个环岛,走第二个出口。"},{"who":"A","en":"The second exit at the roundabout. And then where is it?","zh":"在环岛走第二个出口。然后它在哪儿呢?"},{"who":"B","en":"The station is right there on your right, next to a red-brick post office. You can't miss it.","zh":"火车站就在你右手边,挨着一家红砖邮局。你肯定能找到。"},{"who":"A","en":"That's really helpful. Thank you so much for your help!","zh":"真是太有帮助了。非常感谢您的帮忙!"},{"who":"B","en":"You're very welcome. Have a safe trip!","zh":"不客气。一路平安!"}]},"quiz":[{"type":"mc","prompt":{"zh":"Where does the visitor want to go?","en":"Where does the visitor want to go?"},"options":["The airport","The train station","The bus stop","The city museum"],"correct":1,"feedback":{"zh":"游客一开始就说要去 the train station(火车站)。","en":"The visitor asks for the way to the train station."}},{"type":"mc","prompt":{"zh":"How long does the local say the walk will take?","en":"How long does the local say the walk will take?"},"options":["About two minutes","About five minutes","About ten minutes","About twenty minutes"],"correct":2,"feedback":{"zh":"当地人说 \"about a ten-minute walk\" = 大约走十分钟。","en":"He says it's about a ten-minute walk."}},{"type":"mc","prompt":{"zh":"What should the visitor do at the traffic lights?","en":"What should the visitor do at the traffic lights?"},"options":["Turn left onto Queen Street","Turn right onto Queen Street","Keep going straight ahead","Cross the road and go back"],"correct":0,"feedback":{"zh":"\"At the lights, turn left onto Queen Street\" = 红绿灯处左转。","en":"Turn left onto Queen Street at the lights."}},{"type":"mc","prompt":{"zh":"What should the visitor do at the roundabout?","en":"What should the visitor do at the roundabout?"},"options":["Take the first exit","Take the second exit","Take the third exit","Go all the way around"],"correct":1,"feedback":{"zh":"\"take the second exit\" = 走第二个出口。","en":"Take the second exit at the roundabout."}},{"type":"mc","prompt":{"zh":"What is the train station next to?","en":"What is the train station next to?"},"options":["A blue supermarket","A green city park","A large car park","A red-brick post office"],"correct":3,"feedback":{"zh":"车站 \"next to a red-brick post office\" = 挨着一家红砖邮局。","en":"It's next to a red-brick post office."}}]},"au3":{"caption":{"zh":"听一段诊所语音留言,抓住新的日期、时间和回电号码。","en":"A voicemail from a clinic — catch the new date, time, and callback number."},"listening":{"intro":{"zh":"听一段电话语音留言(牙科诊所改约),记下关键信息后回答问题。","en":"Listen to a phone voicemail from a dental clinic changing an appointment. Note the key details, then answer the questions below."},"lines":[{"en":"Hello, this is a message for Mr. Daniel Brooks.","zh":"您好,这是给 Daniel Brooks 先生的留言。"},{"en":"This is Sarah calling from the Greenfield Dental Clinic.","zh":"我是 Greenfield 牙科诊所的 Sarah。"},{"en":"I'm calling about your check-up appointment, which was booked for this Thursday.","zh":"我打来是关于您预约在本周四的检查。"},{"en":"Unfortunately, the dentist is not available that day, so we need to move your appointment.","zh":"很不巧,牙医那天没空,所以我们需要给您改期。"},{"en":"We'd like to reschedule it for Monday, the fifteenth of September, at half past two in the afternoon.","zh":"我们想把它改到 9 月 15 日(周一)下午两点半。"},{"en":"If that time doesn't suit you, please give us a call back and we'll arrange another one.","zh":"如果那个时间您不方便,请给我们回电,我们再另约。"},{"en":"Our number is 0-1-6-3-5, 5-5-0-2-9-8.","zh":"我们的电话是 0-1-6-3-5,5-5-0-2-9-8。"},{"en":"Also, please remember to bring your insurance card with you.","zh":"另外,请记得带上您的保险卡。"},{"en":"And it really helps if you arrive about ten minutes early to fill in a short form.","zh":"如果您能提前大约十分钟到,填一张简短的表格,那就再好不过了。"},{"en":"Thank you, and we look forward to seeing you. Goodbye.","zh":"谢谢,我们期待与您见面。再见。"}]},"quiz":[{"type":"mc","prompt":{"zh":"Who is the voicemail message for?","en":"Who is the voicemail message for?"},"options":["Mr. David Brooks","Mr. Daniel Brooks","Ms. Sarah Green","Dr. Greenfield"],"correct":1,"feedback":{"zh":"开头说 \"a message for Mr. Daniel Brooks\";Sarah 是打电话的人。","en":"The message is for Mr. Daniel Brooks; Sarah is the caller."}},{"type":"mc","prompt":{"zh":"Why is the clinic calling?","en":"Why is the clinic calling?"},"options":["To confirm the original Thursday time","To cancel the appointment for good","To ask him to pay a bill","To move the appointment to another day"],"correct":3,"feedback":{"zh":"牙医那天没空,所以 \"we need to move your appointment\" = 改到别的一天。","en":"The dentist isn't free, so they need to move the appointment to another day."}},{"type":"mc","prompt":{"zh":"What is the NEW date and time of the appointment?","en":"What is the NEW date and time of the appointment?"},"options":["Thursday at 2:30 pm","Monday, 15 September, at 2:30 pm","Monday, 5 September, at 3:30 pm","Friday, 15 September, at 2:00 pm"],"correct":1,"feedback":{"zh":"\"Monday, the fifteenth of September, at half past two\" = 9 月 15 日周一下午 2:30。","en":"Monday, 15 September, at half past two (2:30 pm)."}},{"type":"mc","prompt":{"zh":"What is the callback number?","en":"What is the callback number?"},"options":["01635 550298","01653 550289","01635 505298","01636 550298"],"correct":0,"feedback":{"zh":"号码是 0-1-6-3-5,5-5-0-2-9-8 = 01635 550298。","en":"The number is 01635 550298."}},{"type":"mc","prompt":{"zh":"What are you asked to do before the appointment?","en":"What are you asked to do before the appointment?"},"options":["Bring a passport and pay a deposit","Bring nothing and just turn up on time","Bring your insurance card and arrive about ten minutes early","Bring a form the clinic posted to you"],"correct":2,"feedback":{"zh":"留言让你带保险卡,并提前大约十分钟到填表。","en":"Bring your insurance card and arrive about ten minutes early to fill in a form."}}]},"au4":{"caption":{"zh":"听两则机场/车站广播,抓住航班、登机口、时间与延误信息。","en":"Two airport/station announcements — catch the flight, gate, time and delay."},"listening":{"intro":{"zh":"听两则公共广播(一则机场、一则火车站),然后回答下面的问题。","en":"Listen to two public-address announcements — one at an airport and one at a train station — then answer the questions below."},"lines":[{"en":"Good afternoon, passengers. This is the final call for British Airways flight BA 249 to Madrid.","zh":"各位旅客下午好。这是英国航空 BA 249 次飞往马德里航班的最后一次登机广播。"},{"en":"The flight is now boarding at gate 32, and the gate will close at 2:20 this afternoon.","zh":"该航班现在正在 32 号登机口登机,登机口将于今天下午 2:20 关闭。"},{"en":"Please note that the gate has changed from gate 15 to gate 32, so please make your way there straight away.","zh":"请注意,登机口已由 15 号变更为 32 号,请立即前往。"},{"en":"Any passengers who are not on board by the closing time may not be able to travel.","zh":"在关闭时间之前尚未登机的旅客可能将无法乘坐本次航班。"},{"en":"Attention, please, on platform 4.","zh":"请 4 号站台的旅客注意。"},{"en":"We are sorry to announce that the 3:05 train to Manchester Piccadilly is delayed by 20 minutes.","zh":"我们很抱歉地通知,3:05 开往曼彻斯特皮卡迪利站的列车晚点 20 分钟。"},{"en":"The train will now depart from platform 4 at approximately 3:25 this afternoon.","zh":"该列车现将于今天下午约 3:25 从 4 号站台发车。"},{"en":"This delay is due to a signalling problem earlier on the line, and we apologise for any inconvenience.","zh":"本次晚点是由于此前线路上的信号故障造成的,给您带来不便,我们深表歉意。"},{"en":"Please check the departure boards for the latest information, and listen for further announcements.","zh":"请查看出发信息屏获取最新信息,并留意后续广播。"}]},"quiz":[{"type":"mc","prompt":{"zh":"What is the flight number of the flight to Madrid?","en":"What is the flight number of the flight to Madrid?"},"options":["BA 149","BA 249","BA 429","BA 924"],"correct":1,"feedback":{"zh":"广播里说的是 British Airways flight BA 249 to Madrid。","en":"The announcement says British Airways flight BA 249 to Madrid."}},{"type":"mc","prompt":{"zh":"Which gate is the Madrid flight boarding from now?","en":"Which gate is the Madrid flight boarding from now?"},"options":["Gate 15","Gate 23","Gate 32","Gate 12"],"correct":2,"feedback":{"zh":"登机口已从 15 号改到 32 号,现在是 gate 32。","en":"The gate changed from 15 to 32, so it is now gate 32."}},{"type":"mc","prompt":{"zh":"By what time must passengers be on board the Madrid flight?","en":"By what time must passengers be on board the Madrid flight?"},"options":["2:20 in the afternoon","3:25 in the afternoon","3:05 in the afternoon","2:15 in the afternoon"],"correct":0,"feedback":{"zh":"广播说 the gate will close at 2:20 this afternoon(2:20 关闭)。","en":"The gate closes at 2:20 in the afternoon."}},{"type":"mc","prompt":{"zh":"What is the problem with the train to Manchester Piccadilly?","en":"What is the problem with the train to Manchester Piccadilly?"},"options":["It has been cancelled","It is delayed by 20 minutes","It is delayed by 15 minutes","It has changed platforms"],"correct":1,"feedback":{"zh":"列车 delayed by 20 minutes,即晚点 20 分钟。","en":"The train is delayed by 20 minutes."}},{"type":"mc","prompt":{"zh":"Why is the train delayed?","en":"Why is the train delayed?"},"options":["Because of bad weather","Because of a staff shortage","Because of an earlier accident","Because of a signalling problem"],"correct":3,"feedback":{"zh":"原因是 a signalling problem(信号故障)。","en":"The delay is due to a signalling problem."}}]},"au5":{"caption":{"zh":"听一段求职面试对话,抓住经历、优势、行为面试题与到岗时间。","en":"A job interview — catch the experience, strength, behavioural question and start date."},"listening":{"intro":{"zh":"听一段求职面试对话(A 是面试官,B 是应聘者),然后回答下面的问题。","en":"Listen to a job interview — A is the interviewer and B is the candidate — then answer the questions below."},"lines":[{"who":"A","en":"Thanks for coming in today. To start, could you tell me a little about your background?","zh":"感谢你今天前来。首先,能简单介绍一下你的经历吗?"},{"who":"B","en":"Of course. I've worked as a marketing assistant for the past three years at a small online shop.","zh":"当然。过去三年我在一家小型网店做市场营销助理。"},{"who":"A","en":"Great. And what would you say is your biggest strength?","zh":"很好。那你觉得自己最大的优势是什么?"},{"who":"B","en":"I'd say I'm very organised. For example, last year I ran all our email campaigns and kept every launch on schedule.","zh":"我会说我做事很有条理。比如去年我负责所有邮件营销活动,让每次上线都按计划准时进行。"},{"who":"A","en":"That's good to hear. Can you tell me about a time you had to deal with a difficult problem at work?","zh":"这很不错。能讲一次你在工作中不得不处理棘手问题的经历吗?"},{"who":"B","en":"Sure. Once a product launch was nearly delayed because a supplier let us down, so I found a backup supplier in two days and we launched on time.","zh":"好的。有一次因为供应商出了问题,产品上线差点被推迟,于是我两天内找到了备用供应商,我们按时上线了。"},{"who":"A","en":"That's impressive. How do you usually handle tight deadlines?","zh":"很了不起。你通常怎么应对紧迫的截止期限?"},{"who":"B","en":"I break big tasks into smaller steps and check my progress every day, so nothing is left to the last minute.","zh":"我会把大任务拆成小步骤,每天检查进度,这样就不会把事情拖到最后一刻。"},{"who":"A","en":"Perfect. If we offered you the role, when would you be able to start?","zh":"很好。如果我们给你这个职位,你什么时候能到岗?"},{"who":"B","en":"I'd need to give my current employer two weeks' notice, so I could start on the first of September.","zh":"我需要向现在的雇主提前两周通知,所以我可以在九月一日入职。"},{"who":"A","en":"That works well for us. Do you have any questions for me?","zh":"这对我们很合适。你有什么想问我的吗?"},{"who":"B","en":"Yes — could you tell me what a typical day in this team looks like?","zh":"有的——能跟我说说这个团队一天通常是怎样的吗?"},{"who":"A","en":"Absolutely. Let's go through that now, and we'll be in touch by the end of the week.","zh":"当然可以。我们现在就来聊聊,我们会在本周末之前和你联系。"}]},"quiz":[{"type":"mc","prompt":{"zh":"How long has the candidate worked as a marketing assistant?","en":"How long has the candidate worked as a marketing assistant?"},"options":["One year","Two years","Three years","Five years"],"correct":2,"feedback":{"zh":"她说 for the past three years,即三年。","en":"She says she has worked there for the past three years."}},{"type":"mc","prompt":{"zh":"What does the candidate say is her biggest strength?","en":"What does the candidate say is her biggest strength?"},"options":["She is very organised","She is very creative","She is good at public speaking","She speaks three languages"],"correct":0,"feedback":{"zh":"她说 I'm very organised(很有条理)。","en":"She says she is very organised."}},{"type":"mc","prompt":{"zh":"How did the candidate deal with the supplier problem?","en":"How did the candidate deal with the supplier problem?"},"options":["She delayed the launch","She cancelled the product","She asked her manager for help","She found a backup supplier in two days"],"correct":3,"feedback":{"zh":"她 found a backup supplier in two days,两天内找到备用供应商。","en":"She found a backup supplier in two days."}},{"type":"mc","prompt":{"zh":"When could the candidate start the new job?","en":"When could the candidate start the new job?"},"options":["Immediately","On the first of September","In three weeks","At the end of the week"],"correct":1,"feedback":{"zh":"她要提前两周通知,能在 the first of September(九月一日)入职。","en":"After two weeks' notice, she could start on the first of September."}},{"type":"mc","prompt":{"zh":"What does the interviewer say will happen next?","en":"What does the interviewer say will happen next?"},"options":["They will offer her the job on the spot","She must take a written test","They will be in touch by the end of the week","She should call back next month"],"correct":2,"feedback":{"zh":"面试官说 we'll be in touch by the end of the week(本周末前联系)。","en":"The interviewer says they will be in touch by the end of the week."}}]},"au6":{"caption":{"zh":"听一段关于蜂蜜如何酿成的科普短讲,先答题再点「显示原文」核对。","en":"A short talk on how honey is made — answer first, then reveal the transcript."},"listening":{"intro":{"zh":"听一段关于蜜蜂如何酿造蜂蜜的短讲,然后回答下面的问题。","en":"Listen to a short talk about how bees make honey, then answer the questions below."},"lines":[{"en":"Have you ever wondered how bees turn flowers into the sweet honey on your toast?","zh":"你有没有想过,蜜蜂是怎么把花变成你面包上那甜甜的蜂蜜的?"},{"en":"It all starts when a worker bee flies from flower to flower, collecting a sugary liquid called nectar.","zh":"一切都始于一只工蜂在花丛间飞来飞去,采集一种叫花蜜的含糖液体。"},{"en":"She stores the nectar in a special part of her body, sometimes called a 'honey stomach', and carries it back to the hive.","zh":"她把花蜜储存在身体里一个特殊的地方——有时叫「蜜胃」——然后带回蜂巢。"},{"en":"Back home, she passes the nectar to other bees, who add natural chemicals called enzymes that slowly change the sugars.","zh":"回到家后,她把花蜜传给其他蜜蜂,它们会加入一种叫酶的天然物质,慢慢改变其中的糖分。"},{"en":"Then the bees spread the liquid across the honeycomb and fan it with their wings to dry it out.","zh":"然后蜜蜂把这些液体铺在巢脾上,用翅膀扇风,把水分吹干。"},{"en":"This fanning removes most of the water, until the thin nectar becomes thick, sticky honey.","zh":"这样的扇风会带走大部分水分,直到稀薄的花蜜变成浓稠黏腻的蜂蜜。"},{"en":"To fill just one small jar, bees may have to visit more than a million flowers.","zh":"仅仅装满一小罐蜂蜜,蜜蜂可能要拜访一百多万朵花。"},{"en":"When the honey is ready, the bees seal each cell with a thin cap of wax to keep it fresh for the winter.","zh":"蜂蜜做好后,蜜蜂会用一层薄薄的蜡把每个蜂房封住,让它在冬天保持新鲜。"},{"en":"Because honey has so little water and is naturally acidic, it almost never goes bad.","zh":"由于蜂蜜含水极少又天然呈酸性,它几乎永远不会变质。"},{"en":"In fact, jars of honey found in ancient tombs were still good to eat thousands of years later.","zh":"事实上,在古墓里发现的蜂蜜,几千年后依然可以食用。"},{"en":"So the next time you taste honey, remember it is really the hard work of thousands of tiny bees.","zh":"所以下次你尝到蜂蜜时,记住:那其实是成千上万只小蜜蜂辛勤劳动的成果。"}]},"quiz":[{"type":"mc","prompt":{"zh":"What is the talk mainly about?","en":"What is the talk mainly about?"},"options":["How to start beekeeping at home","How bees turn nectar into honey","Why bees are disappearing","How flowers grow in spring"],"correct":1,"feedback":{"zh":"全篇围绕蜜蜂如何把花蜜变成蜂蜜,是主旨。","en":"The whole talk explains how bees turn nectar into honey."}},{"type":"mc","prompt":{"zh":"Where does a worker bee first store the nectar she collects?","en":"Where does a worker bee first store the nectar she collects?"},"options":["In the honeycomb","In a bag on her legs","In a wax cup","In a special 'honey stomach'"],"correct":3,"feedback":{"zh":"讲到她把花蜜存在身体里一个特殊的地方,叫「honey stomach 蜜胃」。","en":"She keeps it in a special part of her body, a 'honey stomach'."}},{"type":"mc","prompt":{"zh":"Why do the bees fan the nectar with their wings?","en":"Why do the bees fan the nectar with their wings?"},"options":["To remove most of the water","To keep the hive warm","To call other bees over","To cool the honey down for eating"],"correct":0,"feedback":{"zh":"扇翅膀是为了「dry it out」,带走大部分水分。","en":"Fanning dries the nectar by removing most of the water."}},{"type":"mc","prompt":{"zh":"About how many flowers might bees visit to fill one small jar of honey?","en":"About how many flowers might bees visit to fill one small jar of honey?"},"options":["About a hundred","About a thousand","More than a million","Exactly ten thousand"],"correct":2,"feedback":{"zh":"原文说「more than a million flowers」——一百多万朵。","en":"The talk says more than a million flowers for one small jar."}},{"type":"mc","prompt":{"zh":"What does the example of honey found in ancient tombs suggest?","en":"What does the example of honey found in ancient tombs suggest?"},"options":["Honey must be eaten within a week","Honey was only made long ago","Ancient people disliked honey","Honey can last for thousands of years without spoiling"],"correct":3,"feedback":{"zh":"古墓蜂蜜几千年后仍可食用,说明蜂蜜能保存极久、几乎不坏。","en":"It shows honey can survive for thousands of years without going bad."}}]}});
